create or replace function public.fill_name() returns trigger language plpgsql security definer set search_path = public as $$ begin new.name := coalesce((select left(name, 24) from profiles where id = new.author), 'Viajante'); return new; end $$;
drop trigger if exists fill_name_chat on public.chat;
create trigger fill_name_chat before insert on public.chat for each row execute function public.fill_name();
drop trigger if exists fill_name_posts on public.posts;
create trigger fill_name_posts before insert on public.posts for each row execute function public.fill_name();
drop trigger if exists fill_name_comments on public.comments;
create trigger fill_name_comments before insert on public.comments for each row execute function public.fill_name();
create table if not exists public.blocks (blocker uuid not null default auth.uid() references auth.users(id) on delete cascade, blocked uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (blocker, blocked), check (blocker <> blocked));
alter table public.blocks enable row level security;
drop policy if exists "bloqueios: ler os meus" on public.blocks;
create policy "bloqueios: ler os meus" on public.blocks for select to authenticated using (blocker = auth.uid());
drop policy if exists "bloqueios: criar os meus" on public.blocks;
create policy "bloqueios: criar os meus" on public.blocks for insert to authenticated with check (blocker = auth.uid());
drop policy if exists "bloqueios: remover os meus" on public.blocks;
create policy "bloqueios: remover os meus" on public.blocks for delete to authenticated using (blocker = auth.uid());
create or replace function public.is_blocked(a uuid, b uuid) returns boolean language sql security definer stable set search_path = public as $$ select exists (select 1 from blocks where blocker = a and blocked = b) $$;
drop policy if exists "mensagens: enviar" on public.messages;
create policy "mensagens: enviar" on public.messages for insert to authenticated with check (author = auth.uid() and not public.is_blocked(recipient, author));
create table if not exists public.user_reports (id uuid primary key default gen_random_uuid(), reporter uuid not null, target uuid not null, ctx text not null, excerpt text not null default '', reason text not null default '', created_at timestamptz not null default now());
alter table public.user_reports enable row level security;
create or replace function public.report_user(target uuid, ctx text, excerpt text, reason text) returns jsonb language plpgsql security definer set search_path = public as $$ begin if auth.uid() is null then raise exception 'login necessário'; end if; if target = auth.uid() then raise exception 'você não pode denunciar a si mesmo'; end if; if (select count(*) from user_reports where reporter = auth.uid() and created_at > now() - interval '1 hour') >= 20 then raise exception 'limite de denúncias por hora'; end if; insert into user_reports (reporter, target, ctx, excerpt, reason) values (auth.uid(), target, left(coalesce(ctx, ''), 20), left(coalesce(excerpt, ''), 200), left(coalesce(reason, ''), 100)); return jsonb_build_object('ok', true); end $$;
create or replace function public.admin_reports() returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; return coalesce((select jsonb_agg(r) from (select x.id, x.ctx, x.excerpt, x.reason, x.created_at, x.target as target_id, tp.name as target_name, rp.name as reporter_name from user_reports x left join profiles tp on tp.id = x.target left join profiles rp on rp.id = x.reporter order by x.created_at desc limit 40) r), '[]'::jsonb); end $$;
create or replace function public.admin_resolve_report(rid uuid) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; delete from user_reports where id = rid; return jsonb_build_object('ok', true); end $$;
do $$ begin begin alter publication supabase_realtime add table public.chat; exception when others then null; end; end $$;
